import { PageHeaderModule } from 'src/app/view/components/app/page-header/page-header.module';
import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';

import { DoersRoutingModule } from './doers-routing.module';
import { DoersComponent } from './doers.component';
import { FormsModule } from '@angular/forms';
import { IonicModule } from '@ionic/angular';
import { FooterModule } from 'src/app/view/components/app/footer/footer.module';

import { LoadingModule } from 'src/app/view/components/common/loading/loading.module';
import { UserService } from '../../../../data/service/user/user.service';
import { HTTP_INTERCEPTORS } from '@angular/common/http';
import { AccountInterceptor } from 'src/app/core/utility/account.interceptor';
import { PriceModule } from '../../../../core/pipe/price.module';


@NgModule({
  declarations: [DoersComponent],
  imports: [
    PageHeaderModule,
    CommonModule,
    DoersRoutingModule,
    
    FooterModule,
    FormsModule,
    IonicModule,
    LoadingModule,
    PriceModule
  ],
  providers: [
    UserService,
    {
      provide: HTTP_INTERCEPTORS,
      useClass: AccountInterceptor,
      multi: true
    }
  ]
})
export class DoersModule { }
